package world

import (
	"strconv"
	"strings"

	"regionio/internal/nbt"
	"regionio/internal/worldgen"
)

// StructureBlockEntity represents a block entity generated by a structure or feature
// (chests, barrels, dispensers, brewing stands, decorated pots, brushable blocks,
// mob spawners, trial spawners, vaults).
type StructureBlockEntity struct {
	ID              string                   // e.g. "minecraft:chest", "minecraft:barrel", "minecraft:dispenser", "minecraft:brewing_stand", "minecraft:decorated_pot", "minecraft:brushable_block", "minecraft:mob_spawner", "minecraft:trial_spawner", "minecraft:vault"
	X, Y, Z         int                      // World block coordinates
	LootTable       string                   // e.g. "minecraft:chests/simple_dungeon", "minecraft:archaeology/desert_pyramid"
	LootTableSeed   int64                    // Seed for loot table evaluation
	Items           []worldgen.LootItemStack // Evaluated or template-fixed items
	SpawnerEntityID string                   // For mob_spawner / trial_spawner: e.g. "minecraft:zombie", "minecraft:blaze", "minecraft:breeze"
	NormalConfig    string                   // For trial_spawner: e.g. "minecraft:trial_chamber/breeze/normal"
	OminousConfig   string                   // For trial_spawner: e.g. "minecraft:trial_chamber/breeze/ominous"
	KeyItem         string                   // For vault: "minecraft:trial_key" or "minecraft:ominous_trial_key"
	Sherds          []string                 // For decorated_pot
}

// StructureEntity represents a persistent mob or entity spawned by a structure
// (elder_guardian, evoker, vindicator, allay, piglin, piglin_brute, hoglin,
// shulker, item_frame with elytra, villager, zombie_villager, drowned, iron_golem,
// chest_minecart, witch, cat, wither_skeleton, blaze).
type StructureEntity struct {
	ID                     string                   // e.g. "minecraft:elder_guardian", "minecraft:shulker", "minecraft:piglin_brute"
	X, Y, Z                float64                  // World position
	BlockX, BlockY, BlockZ int                      // World block position
	Rotation               int                      // Facing / rotation (0..3)
	PersistenceRequired    bool                     // True for persistent structure mobs
	LootTable              string                   // For chest_minecart: "minecraft:chests/abandoned_mineshaft"
	LootTableSeed          int64                    // Seed for loot table evaluation
	Item                   string                   // For item_frame: "minecraft:elytra"
	Items                  []worldgen.LootItemStack // Evaluated loot items
}

func blockPosAsLong(x, y, z int) int64 {
	return ((int64(x) & 0x3FFFFFF) << 38) | (int64(y) & 0xFFF) | ((int64(z) & 0x3FFFFFF) << 12)
}

func defaultContainerSize(beID string) int {
	switch normalizeResourceID(beID) {
	case "minecraft:chest", "minecraft:trapped_chest", "minecraft:barrel", "minecraft:shulker_box":
		return 27
	case "minecraft:dispenser", "minecraft:dropper", "minecraft:crafter":
		return 9
	case "minecraft:hopper", "minecraft:brewing_stand":
		return 5
	case "minecraft:furnace", "minecraft:blast_furnace", "minecraft:smoker":
		return 3
	case "minecraft:brushable_block", "minecraft:decorated_pot":
		return 1
	case "minecraft:vault":
		return 9
	default:
		return 27
	}
}

func populateBlockEntityLoot(be *StructureBlockEntity) {
	be.ID = normalizeResourceID(be.ID)
	if be.LootTable != "" {
		be.LootTable = normalizeResourceID(be.LootTable)
	}
	if be.SpawnerEntityID != "" {
		be.SpawnerEntityID = normalizeResourceID(be.SpawnerEntityID)
	}
	if be.NormalConfig != "" {
		be.NormalConfig = normalizeResourceID(be.NormalConfig)
	}
	if be.OminousConfig != "" {
		be.OminousConfig = normalizeResourceID(be.OminousConfig)
	}
	if be.KeyItem != "" {
		be.KeyItem = normalizeResourceID(be.KeyItem)
	}
	reg, err := worldgen.LoadLootAndSpawnerRegistry()
	if err != nil || reg == nil {
		return
	}
	if be.ID == "minecraft:trial_spawner" && be.SpawnerEntityID == "" && be.NormalConfig != "" {
		if cfg := reg.GetTrialSpawnerConfig(be.NormalConfig); cfg != nil {
			be.SpawnerEntityID = cfg.PrimaryEntityID()
		}
	}
	if be.LootTable != "" && len(be.Items) == 0 {
		sz := defaultContainerSize(be.ID)
		if sz == 1 {
			items := reg.GenerateLoot(be.LootTable, be.LootTableSeed)
			if len(items) > 0 {
				be.Items = items[:1]
			}
		} else {
			be.Items = reg.FillContainer(be.LootTable, be.LootTableSeed, sz)
		}
	}
}

func populateEntityLoot(ent *StructureEntity) {
	ent.ID = normalizeResourceID(ent.ID)
	if ent.LootTable != "" {
		ent.LootTable = normalizeResourceID(ent.LootTable)
	}
	if ent.Item != "" {
		ent.Item = normalizeResourceID(ent.Item)
	}
	if ent.LootTable != "" && len(ent.Items) == 0 {
		if reg, err := worldgen.LoadLootAndSpawnerRegistry(); err == nil && reg != nil {
			ent.Items = reg.FillContainer(ent.LootTable, ent.LootTableSeed, 27)
		}
	}
}

// AddStructureBlockEntity records or updates a structural block entity on the chunk.
func (c *Chunk) AddStructureBlockEntity(be StructureBlockEntity) {
	if c == nil {
		return
	}
	populateBlockEntityLoot(&be)
	c.mu.Lock()
	defer c.mu.Unlock()
	for i := range c.blockEntities {
		if c.blockEntities[i].X == be.X && c.blockEntities[i].Y == be.Y && c.blockEntities[i].Z == be.Z {
			c.blockEntities[i] = be
			return
		}
	}
	c.blockEntities = append(c.blockEntities, be)
}

// RemoveStructureBlockEntity removes any structural block entity at (x, y, z) on the chunk.
func (c *Chunk) RemoveStructureBlockEntity(x, y, z int) {
	if c == nil {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	for i := range c.blockEntities {
		if c.blockEntities[i].X == x && c.blockEntities[i].Y == y && c.blockEntities[i].Z == z {
			c.blockEntities = append(c.blockEntities[:i], c.blockEntities[i+1:]...)
			return
		}
	}
}

// MoveStructureBlockEntity moves a structural block entity from (fromX, fromY, fromZ)
// to (toX, toY, toZ) within the chunk (e.g. when a brushable block falls).
func (c *Chunk) MoveStructureBlockEntity(fromX, fromY, fromZ, toX, toY, toZ int) {
	if c == nil {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	for i := range c.blockEntities {
		if c.blockEntities[i].X == fromX && c.blockEntities[i].Y == fromY && c.blockEntities[i].Z == fromZ {
			c.blockEntities[i].X = toX
			c.blockEntities[i].Y = toY
			c.blockEntities[i].Z = toZ
			return
		}
	}
}

// StructureBlockEntities returns a copy of all structural block entities on the chunk.
func (c *Chunk) StructureBlockEntities() []StructureBlockEntity {
	if c == nil {
		return nil
	}
	c.mu.RLock()
	defer c.mu.RUnlock()
	if len(c.blockEntities) == 0 {
		return nil
	}
	out := make([]StructureBlockEntity, len(c.blockEntities))
	copy(out, c.blockEntities)
	return out
}

// StructureBlockEntityAt returns the structural block entity at world (x, y, z), if any.
func (c *Chunk) StructureBlockEntityAt(x, y, z int) (StructureBlockEntity, bool) {
	if c == nil {
		return StructureBlockEntity{}, false
	}
	c.mu.RLock()
	defer c.mu.RUnlock()
	for _, be := range c.blockEntities {
		if be.X == x && be.Y == y && be.Z == z {
			return be, true
		}
	}
	return StructureBlockEntity{}, false
}

// AddStructureEntity records a structural entity on the chunk, deduplicating by (ID, BlockX, BlockY, BlockZ).
func (c *Chunk) AddStructureEntity(ent StructureEntity) {
	if c == nil || ent.ID == "" {
		return
	}
	populateEntityLoot(&ent)
	c.mu.Lock()
	defer c.mu.Unlock()
	for i := range c.entities {
		e := &c.entities[i]
		if e.ID == ent.ID && e.BlockX == ent.BlockX && e.BlockY == ent.BlockY && e.BlockZ == ent.BlockZ {
			c.entities[i] = ent
			return
		}
	}
	c.entities = append(c.entities, ent)
}

// StructureEntities returns a copy of all structural entities on the chunk.
func (c *Chunk) StructureEntities() []StructureEntity {
	if c == nil {
		return nil
	}
	c.mu.RLock()
	defer c.mu.RUnlock()
	if len(c.entities) == 0 {
		return nil
	}
	out := make([]StructureEntity, len(c.entities))
	copy(out, c.entities)
	return out
}

func (r *decorationRegion) addStructureBlockEntity(be StructureBlockEntity) {
	if r == nil {
		return
	}
	ch := r.chunks[[2]int32{int32(be.X >> 4), int32(be.Z >> 4)}]
	if ch != nil {
		ch.AddStructureBlockEntity(be)
	}
}

func (r *decorationRegion) removeStructureBlockEntity(x, y, z int) {
	if r == nil {
		return
	}
	ch := r.chunks[[2]int32{int32(x >> 4), int32(z >> 4)}]
	if ch != nil {
		ch.RemoveStructureBlockEntity(x, y, z)
	}
}

func defaultBlockEntityForBlock(blockName string, x, y, z int) (StructureBlockEntity, bool) {
	name := normalizeResourceID(blockName)
	var beID string
	switch name {
	case "minecraft:barrel",
		"minecraft:chest",
		"minecraft:trapped_chest",
		"minecraft:dispenser",
		"minecraft:dropper",
		"minecraft:crafter",
		"minecraft:hopper",
		"minecraft:brewing_stand",
		"minecraft:furnace",
		"minecraft:blast_furnace",
		"minecraft:smoker",
		"minecraft:decorated_pot",
		"minecraft:chiseled_bookshelf",
		"minecraft:lectern",
		"minecraft:jukebox",
		"minecraft:bell",
		"minecraft:campfire",
		"minecraft:soul_campfire",
		"minecraft:beehive",
		"minecraft:sculk_sensor",
		"minecraft:calibrated_sculk_sensor",
		"minecraft:sculk_catalyst",
		"minecraft:sculk_shrieker",
		"minecraft:conduit",
		"minecraft:ender_chest",
		"minecraft:daylight_detector",
		"minecraft:enchanting_table",
		"minecraft:beacon",
		"minecraft:comparator",
		"minecraft:trial_spawner",
		"minecraft:vault",
		"minecraft:creaking_heart":
		beID = name
	case "minecraft:bee_nest":
		beID = "minecraft:beehive"
	case "minecraft:spawner":
		beID = "minecraft:mob_spawner"
	case "minecraft:suspicious_sand", "minecraft:suspicious_gravel":
		beID = "minecraft:brushable_block"
	default:
		if strings.HasSuffix(name, "_shulker_box") || name == "minecraft:shulker_box" {
			beID = "minecraft:shulker_box"
		} else if strings.HasSuffix(name, "_bed") {
			beID = "minecraft:bed"
		} else if strings.HasSuffix(name, "_banner") {
			beID = "minecraft:banner"
		} else if strings.HasSuffix(name, "_hanging_sign") {
			beID = "minecraft:hanging_sign"
		} else if strings.HasSuffix(name, "_sign") {
			beID = "minecraft:sign"
		} else if strings.HasSuffix(name, "_skull") || strings.HasSuffix(name, "_head") {
			beID = "minecraft:skull"
		} else {
			return StructureBlockEntity{}, false
		}
	}
	return StructureBlockEntity{
		ID: beID,
		X:  x,
		Y:  y,
		Z:  z,
	}, true
}

func (r *decorationRegion) moveStructureBlockEntity(fromX, fromY, fromZ, toX, toY, toZ int) {
	if r == nil {
		return
	}
	ch := r.chunks[[2]int32{int32(fromX >> 4), int32(fromZ >> 4)}]
	if ch != nil {
		ch.MoveStructureBlockEntity(fromX, fromY, fromZ, toX, toY, toZ)
	}
}

func (r *decorationRegion) addStructureEntity(ent StructureEntity) {
	if r == nil {
		return
	}
	ch := r.chunks[[2]int32{int32(ent.BlockX >> 4), int32(ent.BlockZ >> 4)}]
	if ch != nil {
		ch.AddStructureEntity(ent)
	}
}

func beNBTString(nc *nbt.Compound, key string) string {
	if nc == nil {
		return ""
	}
	if v, ok := nc.Get(key); ok {
		if s, isStr := v.(nbt.String); isStr {
			return string(s)
		}
	}
	return ""
}

func beNBTInt(nc *nbt.Compound, key string, def int) int {
	if nc == nil {
		return def
	}
	if v, ok := nc.Get(key); ok {
		switch iv := v.(type) {
		case nbt.Byte:
			return int(iv)
		case nbt.Short:
			return int(iv)
		case nbt.Int:
			return int(iv)
		case nbt.Long:
			return int(iv)
		}
	}
	return def
}

// extractTemplateBlockEntity extracts a StructureBlockEntity from a template block's NBT compound.
func extractTemplateBlockEntity(worldX, worldY, worldZ int, blockName string, nc *nbt.Compound, lootSeed int64) (StructureBlockEntity, bool) {
	if nc == nil {
		return StructureBlockEntity{}, false
	}
	id := beNBTString(nc, "id")
	if id == "" {
		switch normalizeResourceID(blockName) {
		case "minecraft:spawner":
			id = "minecraft:mob_spawner"
		case "minecraft:suspicious_sand", "minecraft:suspicious_gravel":
			id = "minecraft:brushable_block"
		default:
			id = normalizeResourceID(blockName)
		}
	} else {
		id = normalizeResourceID(id)
	}
	if id == "minecraft:jigsaw" || id == "minecraft:structure_block" {
		return StructureBlockEntity{}, false
	}

	be := StructureBlockEntity{
		ID:            id,
		X:             worldX,
		Y:             worldY,
		Z:             worldZ,
		LootTable:     beNBTString(nc, "LootTable"),
		LootTableSeed: lootSeed,
	}

	// 1. Parse fixed Items list if present (e.g. end_city/ship brewing stand, igloo brewing stand, trial chamber / village containers).
	if itemsTag, ok := nc.Get("Items"); ok {
		if list, isList := itemsTag.(nbt.List); isList {
			for _, elem := range list.Elems {
				ic, ok := elem.(*nbt.Compound)
				if !ok {
					continue
				}
				itemID := beNBTString(ic, "id")
				if itemID == "" {
					continue
				}
				count := beNBTInt(ic, "count", beNBTInt(ic, "Count", 1))
				if count <= 0 {
					count = 1
				}
				slot := beNBTInt(ic, "Slot", len(be.Items))
				var potionID string
				if tagVal, ok := ic.Get("tag"); ok {
					if tc, ok := tagVal.(*nbt.Compound); ok {
						potionID = beNBTString(tc, "Potion")
					}
				}
				if compVal, ok := ic.Get("components"); ok {
					if cc, ok := compVal.(*nbt.Compound); ok {
						if potVal, ok := cc.Get("minecraft:potion_contents"); ok {
							switch pv := potVal.(type) {
							case nbt.String:
								potionID = string(pv)
							case *nbt.Compound:
								potionID = beNBTString(pv, "potion")
							}
						}
					}
				}
				be.Items = append(be.Items, worldgen.LootItemStack{
					Slot:     slot,
					ItemID:   normalizeResourceID(itemID),
					Count:    count,
					PotionID: potionID,
				})
			}
		}
	}

	// 2. Decorated pot sherds and single item.
	if id == "minecraft:decorated_pot" {
		if sherdsTag, ok := nc.Get("sherds"); ok {
			if list, isList := sherdsTag.(nbt.List); isList {
				for _, elem := range list.Elems {
					if s, isStr := elem.(nbt.String); isStr && string(s) != "" {
						be.Sherds = append(be.Sherds, normalizeResourceID(string(s)))
					}
				}
			}
		}
		if itemTag, ok := nc.Get("item"); ok {
			if ic, isComp := itemTag.(*nbt.Compound); isComp {
				itemID := beNBTString(ic, "id")
				if itemID != "" {
					cnt := beNBTInt(ic, "count", beNBTInt(ic, "Count", 1))
					if cnt <= 0 {
						cnt = 1
					}
					be.Items = append(be.Items, worldgen.LootItemStack{
						Slot:   0,
						ItemID: normalizeResourceID(itemID),
						Count:  cnt,
					})
				}
			}
		}
	}

	// 3. Mob Spawner (SpawnData.entity.id).
	if id == "minecraft:mob_spawner" || id == "minecraft:spawner" {
		be.ID = "minecraft:mob_spawner"
		if sdTag, ok := nc.Get("SpawnData"); ok {
			if sdc, isComp := sdTag.(*nbt.Compound); isComp {
				if entTag, ok := sdc.Get("entity"); ok {
					if ec, isComp := entTag.(*nbt.Compound); isComp {
						be.SpawnerEntityID = beNBTString(ec, "id")
					}
				}
				if be.SpawnerEntityID == "" {
					be.SpawnerEntityID = beNBTString(sdc, "id")
				}
			}
		}
	}

	// 4. Trial Spawner (normal_config, ominous_config).
	if id == "minecraft:trial_spawner" {
		be.NormalConfig = beNBTString(nc, "normal_config")
		be.OminousConfig = beNBTString(nc, "ominous_config")
		if be.NormalConfig == "" {
			if ncTag, ok := nc.Get("normal_config"); ok {
				if ncc, isComp := ncTag.(*nbt.Compound); isComp {
					be.NormalConfig = "inline"
					if be.SpawnerEntityID == "" {
						be.SpawnerEntityID = extractTrialSpawnerInlineEntity(ncc)
					}
				}
			}
		}
		if be.OminousConfig == "" {
			if ocTag, ok := nc.Get("ominous_config"); ok {
				if occ, isComp := ocTag.(*nbt.Compound); isComp {
					be.OminousConfig = "inline"
					if be.SpawnerEntityID == "" {
						be.SpawnerEntityID = extractTrialSpawnerInlineEntity(occ)
					}
				}
			}
		}
	}

	// 5. Vault (config.loot_table, config.key_item.id).
	if id == "minecraft:vault" {
		if cfgTag, ok := nc.Get("config"); ok {
			if cfgComp, isComp := cfgTag.(*nbt.Compound); isComp {
				if lt := beNBTString(cfgComp, "loot_table"); lt != "" {
					be.LootTable = lt
				}
				if keyTag, ok := cfgComp.Get("key_item"); ok {
					if kc, isComp := keyTag.(*nbt.Compound); isComp {
						be.KeyItem = beNBTString(kc, "id")
					}
				}
			}
		}
		if be.LootTable == "" {
			be.LootTable = "minecraft:chests/trial_chambers/reward"
		}
		if be.KeyItem == "" {
			if strings.Contains(be.LootTable, "ominous") {
				be.KeyItem = "minecraft:ominous_trial_key"
			} else {
				be.KeyItem = "minecraft:trial_key"
			}
		}
		if be.LootTableSeed == 0 {
			be.LootTableSeed = blockPosAsLong(worldX, worldY, worldZ)
		}
	}

	// 6. Lectern book (e.g. Ancient City redstone lab / Village library).
	if id == "minecraft:lectern" && len(be.Items) == 0 {
		if bookTag, ok := nc.Get("Book"); ok {
			if bc, isComp := bookTag.(*nbt.Compound); isComp {
				itemID := beNBTString(bc, "id")
				if itemID != "" {
					cnt := beNBTInt(bc, "count", beNBTInt(bc, "Count", 1))
					if cnt <= 0 {
						cnt = 1
					}
					be.Items = append(be.Items, worldgen.LootItemStack{
						Slot:   0,
						ItemID: normalizeResourceID(itemID),
						Count:  cnt,
					})
				}
			}
		}
	}

	return be, true
}

func extractTrialSpawnerInlineEntity(cfgComp *nbt.Compound) string {
	if cfgComp == nil {
		return ""
	}
	if spTag, ok := cfgComp.Get("spawn_potentials"); ok {
		if list, isList := spTag.(nbt.List); isList {
			for _, elem := range list.Elems {
				ec, ok := elem.(*nbt.Compound)
				if !ok {
					continue
				}
				if dataTag, ok := ec.Get("data"); ok {
					if dc, ok := dataTag.(*nbt.Compound); ok {
						if entTag, ok := dc.Get("entity"); ok {
							if entComp, ok := entTag.(*nbt.Compound); ok {
								if id := beNBTString(entComp, "id"); id != "" {
									return normalizeResourceID(id)
								}
							}
						}
					}
				}
			}
		}
	}
	return ""
}

func mapToNBTCompound(m map[string]any) *nbt.Compound {
	if len(m) == 0 {
		return nil
	}
	comp := nbt.NewCompound()
	for k, v := range m {
		if tag := anyToNBTTag(v); tag != nil {
			comp.Set(k, tag)
		}
	}
	return comp
}

func anyToNBTTag(v any) nbt.Tag {
	switch val := v.(type) {
	case string:
		return nbt.String(val)
	case bool:
		if val {
			return nbt.Byte(1)
		}
		return nbt.Byte(0)
	case float64:
		return nbt.Int(int32(val))
	case int:
		return nbt.Int(int32(val))
	case int64:
		return nbt.Long(val)
	case map[string]any:
		return mapToNBTCompound(val)
	case []any:
		if len(val) == 0 {
			return nbt.List{ElemID: nbt.TagEnd}
		}
		var elems []nbt.Tag
		var elemID byte
		for _, item := range val {
			t := anyToNBTTag(item)
			if t == nil {
				continue
			}
			if elemID == 0 {
				elemID = t.ID()
			}
			elems = append(elems, t)
		}
		return nbt.List{ElemID: elemID, Elems: elems}
	}
	return nil
}

// parseSNBTCompound parses a trailing SNBT compound string "{...}" from a jigsaw final_state.
func parseSNBTCompound(s string) *nbt.Compound {
	p := &snbtParser{s: strings.TrimSpace(s)}
	v := p.parseValue()
	if c, ok := v.(*nbt.Compound); ok {
		return c
	}
	return nil
}

type snbtParser struct {
	s string
	i int
}

func (p *snbtParser) skipWS() {
	for p.i < len(p.s) {
		ch := p.s[p.i]
		if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
			p.i++
		} else {
			break
		}
	}
}

func (p *snbtParser) parseValue() nbt.Tag {
	p.skipWS()
	if p.i >= len(p.s) {
		return nil
	}
	switch p.s[p.i] {
	case '{':
		return p.parseCompound()
	case '[':
		return p.parseList()
	case '"', '\'':
		return nbt.String(p.parseQuoted())
	default:
		return p.parseScalar()
	}
}

func (p *snbtParser) parseCompound() *nbt.Compound {
	if p.i >= len(p.s) || p.s[p.i] != '{' {
		return nil
	}
	p.i++
	comp := nbt.NewCompound()
	for {
		p.skipWS()
		if p.i >= len(p.s) {
			break
		}
		if p.s[p.i] == '}' {
			p.i++
			break
		}
		if p.s[p.i] == ',' {
			p.i++
			continue
		}
		var key string
		if p.s[p.i] == '"' || p.s[p.i] == '\'' {
			key = p.parseQuoted()
		} else {
			start := p.i
			for p.i < len(p.s) && p.s[p.i] != ':' && p.s[p.i] != '}' && p.s[p.i] != ' ' && p.s[p.i] != '\t' {
				p.i++
			}
			key = p.s[start:p.i]
		}
		p.skipWS()
		if p.i < len(p.s) && p.s[p.i] == ':' {
			p.i++
		}
		val := p.parseValue()
		if key != "" && val != nil {
			comp.Set(key, val)
		}
		p.skipWS()
		if p.i < len(p.s) && p.s[p.i] == ',' {
			p.i++
		}
	}
	return comp
}

func (p *snbtParser) parseList() nbt.List {
	if p.i >= len(p.s) || p.s[p.i] != '[' {
		return nbt.List{}
	}
	p.i++
	// Skip optional array type prefix like [I; or [B; or [L;
	if p.i+1 < len(p.s) && p.s[p.i+1] == ';' {
		p.i += 2
	}
	var elems []nbt.Tag
	var elemID byte
	for {
		p.skipWS()
		if p.i >= len(p.s) {
			break
		}
		if p.s[p.i] == ']' {
			p.i++
			break
		}
		if p.s[p.i] == ',' {
			p.i++
			continue
		}
		v := p.parseValue()
		if v != nil {
			if elemID == 0 {
				elemID = v.ID()
			}
			elems = append(elems, v)
		}
		p.skipWS()
		if p.i < len(p.s) && p.s[p.i] == ',' {
			p.i++
		}
	}
	return nbt.List{ElemID: elemID, Elems: elems}
}

func (p *snbtParser) parseQuoted() string {
	quote := p.s[p.i]
	p.i++
	var sb strings.Builder
	for p.i < len(p.s) {
		ch := p.s[p.i]
		p.i++
		if ch == '\\' && p.i < len(p.s) {
			sb.WriteByte(p.s[p.i])
			p.i++
			continue
		}
		if ch == quote {
			break
		}
		sb.WriteByte(ch)
	}
	return sb.String()
}

func (p *snbtParser) parseScalar() nbt.Tag {
	start := p.i
	for p.i < len(p.s) {
		ch := p.s[p.i]
		if ch == ',' || ch == '}' || ch == ']' || ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
			break
		}
		p.i++
	}
	tok := p.s[start:p.i]
	switch tok {
	case "true":
		return nbt.Byte(1)
	case "false":
		return nbt.Byte(0)
	}
	if len(tok) > 1 {
		last := tok[len(tok)-1]
		numPart := tok[:len(tok)-1]
		switch last {
		case 'b', 'B':
			if iv, err := strconv.ParseInt(numPart, 10, 8); err == nil {
				return nbt.Byte(int8(iv))
			}
		case 's', 'S':
			if iv, err := strconv.ParseInt(numPart, 10, 16); err == nil {
				return nbt.Short(int16(iv))
			}
		case 'l', 'L':
			if iv, err := strconv.ParseInt(numPart, 10, 64); err == nil {
				return nbt.Long(iv)
			}
		}
	}
	if iv, err := strconv.ParseInt(tok, 10, 32); err == nil {
		return nbt.Int(int32(iv))
	}
	return nbt.String(tok)
}

func structureBlockEntitiesToNBT(c *Chunk) nbt.List {
	list := nbt.List{ElemID: nbt.TagCompound}
	if c == nil || len(c.blockEntities) == 0 {
		return list
	}
	for _, be := range c.blockEntities {
		comp := nbt.NewCompound().
			Set("id", nbt.String(be.ID)).
			Set("x", nbt.Int(be.X)).
			Set("y", nbt.Int(be.Y)).
			Set("z", nbt.Int(be.Z))
		if be.LootTable != "" {
			comp.Set("LootTable", nbt.String(be.LootTable))
			comp.Set("LootTableSeed", nbt.Long(be.LootTableSeed))
		}
		if be.SpawnerEntityID != "" {
			comp.Set("SpawnData", nbt.NewCompound().Set("entity", nbt.NewCompound().Set("id", nbt.String(be.SpawnerEntityID))))
		}
		if be.NormalConfig != "" {
			comp.Set("normal_config", nbt.String(be.NormalConfig))
		}
		if be.OminousConfig != "" {
			comp.Set("ominous_config", nbt.String(be.OminousConfig))
		}
		if be.KeyItem != "" {
			comp.Set("key_item", nbt.String(be.KeyItem))
		}
		if len(be.Sherds) > 0 {
			sherds := nbt.List{ElemID: nbt.TagString}
			for _, sh := range be.Sherds {
				sherds.Elems = append(sherds.Elems, nbt.String(sh))
			}
			comp.Set("sherds", sherds)
		}
		if len(be.Items) > 0 {
			items := nbt.List{ElemID: nbt.TagCompound}
			for _, it := range be.Items {
				ic := nbt.NewCompound().
					Set("Slot", nbt.Byte(int8(it.Slot))).
					Set("id", nbt.String(it.ItemID)).
					Set("count", nbt.Int(it.Count))
				if it.PotionID != "" {
					ic.Set("Potion", nbt.String(it.PotionID))
				}
				items.Elems = append(items.Elems, ic)
			}
			comp.Set("Items", items)
		}
		list.Elems = append(list.Elems, comp)
	}
	return list
}

func structureBlockEntitiesFromNBT(c *Chunk, root *nbt.Compound) {
	if c == nil || root == nil {
		return
	}
	beTag, ok := root.Get("block_entities")
	if !ok {
		return
	}
	beList, ok := beTag.(nbt.List)
	if !ok || len(beList.Elems) == 0 {
		return
	}
	for _, elem := range beList.Elems {
		comp, ok := elem.(*nbt.Compound)
		if !ok {
			continue
		}
		x := int(nbtAsInt(comp, "x"))
		y := int(nbtAsInt(comp, "y"))
		z := int(nbtAsInt(comp, "z"))
		var seed int64
		if st, ok := comp.Get("LootTableSeed"); ok {
			if l, isLong := st.(nbt.Long); isLong {
				seed = int64(l)
			}
		}
		be, valid := extractTemplateBlockEntity(x, y, z, "", comp, seed)
		if !valid {
			continue
		}
		if ki := beNBTString(comp, "key_item"); ki != "" {
			be.KeyItem = ki
		}
		c.AddStructureBlockEntity(be)
	}
}

// PlaceDesertWell ports net.minecraft.world.level.levelgen.feature.DesertWellFeature.place,
// including the foundation check, 5-sand cross layer at Y-1, and 2 minecraft:suspicious_sand
// blocks with BuiltInLootTables.DESERT_WELL_ARCHAEOLOGY.
func PlaceDesertWell(c *Chunk, ox, oy, oz int) bool {
	return PlaceDesertWellWithRandom(c, worldgen.NewLegacy(blockPosAsLong(ox, oy, oz)), ox, oy, oz)
}

// PlaceDesertWellWithRandom ports DesertWellFeature.place using the provided RandomSource
// to pick the 2 suspicious_sand positions at Y-1 and Y-2 beneath the 5 water cross positions.
func PlaceDesertWellWithRandom(c *Chunk, random worldgen.RandomSource, ox, oy, oz int) bool {
	if c == nil {
		return false
	}
	if random == nil {
		random = worldgen.NewLegacy(blockPosAsLong(ox, oy, oz))
	}
	stateByIDOnce.Do(buildStateTable)
	sand, _ := nameToStateID("minecraft:sand", nil)
	sandstone, _ := nameToStateID("minecraft:sandstone", nil)
	sandstoneSlab, _ := nameToStateID("minecraft:sandstone_slab", map[string]string{"type": "bottom", "waterlogged": "false"})
	water, _ := nameToStateID("minecraft:water", map[string]string{"level": "0"})
	suspiciousSand, _ := nameToStateID("minecraft:suspicious_sand", map[string]string{"dusted": "0"})

	oy++
	for oy > c.minY()+2 && isAirState(c.GetBlock(ox&15, oy, oz&15)) {
		oy--
	}
	cur := c.GetBlock(ox&15, oy, oz&15)
	if cur != sand {
		return false
	}
	for dx := -2; dx <= 2; dx++ {
		for dz := -2; dz <= 2; dz++ {
			if isAirState(c.GetBlock((ox+dx)&15, oy-1, (oz+dz)&15)) && isAirState(c.GetBlock((ox+dx)&15, oy-2, (oz+dz)&15)) {
				return false
			}
		}
	}

	// Base sandstone + water cross + 5-sand cross at oy-1
	for dy := -2; dy <= 0; dy++ {
		for dx := -2; dx <= 2; dx++ {
			for dz := -2; dz <= 2; dz++ {
				c.SetBlock((ox+dx)&15, oy+dy, (oz+dz)&15, sandstone)
			}
		}
	}
	c.SetBlock(ox&15, oy, oz&15, water)
	horiz := [4][2]int{{0, -1}, {1, 0}, {0, 1}, {-1, 0}}
	for _, d := range horiz {
		c.SetBlock((ox+d[0])&15, oy, (oz+d[1])&15, water)
	}
	c.SetBlock(ox&15, oy-1, oz&15, sand)
	for _, d := range horiz {
		c.SetBlock((ox+d[0])&15, oy-1, (oz+d[1])&15, sand)
	}

	// Perimeter slabs and corner pillars + roof
	for dx := -2; dx <= 2; dx++ {
		for dz := -2; dz <= 2; dz++ {
			if dx == -2 || dx == 2 || dz == -2 || dz == 2 {
				c.SetBlock((ox+dx)&15, oy+1, (oz+dz)&15, sandstone)
			}
		}
	}
	c.SetBlock((ox+2)&15, oy+1, oz&15, sandstoneSlab)
	c.SetBlock((ox-2)&15, oy+1, oz&15, sandstoneSlab)
	c.SetBlock(ox&15, oy+1, (oz+2)&15, sandstoneSlab)
	c.SetBlock(ox&15, oy+1, (oz-2)&15, sandstoneSlab)

	for dx := -1; dx <= 1; dx++ {
		for dz := -1; dz <= 1; dz++ {
			if dx == 0 && dz == 0 {
				c.SetBlock(ox&15, oy+4, oz&15, sandstone)
			} else {
				c.SetBlock((ox+dx)&15, oy+4, (oz+dz)&15, sandstoneSlab)
			}
		}
	}
	for dy := 1; dy <= 3; dy++ {
		c.SetBlock((ox-1)&15, oy+dy, (oz-1)&15, sandstone)
		c.SetBlock((ox-1)&15, oy+dy, (oz+1)&15, sandstone)
		c.SetBlock((ox+1)&15, oy+dy, (oz-1)&15, sandstone)
		c.SetBlock((ox+1)&15, oy+dy, (oz+1)&15, sandstone)
	}

	// 2 suspicious_sand blocks placed at Y-1 and Y-2 under randomly chosen water cross positions
	waterPositions := [5][3]int{
		{ox, oy, oz},
		{ox + 1, oy, oz},
		{ox, oy, oz + 1},
		{ox - 1, oy, oz},
		{ox, oy, oz - 1},
	}
	p1 := waterPositions[int(random.NextIntN(5))]
	p1[1] -= 1
	p2 := waterPositions[int(random.NextIntN(5))]
	p2[1] -= 2
	for _, sp := range [2][3]int{p1, p2} {
		c.SetBlock(sp[0]&15, sp[1], sp[2]&15, suspiciousSand)
		c.AddStructureBlockEntity(StructureBlockEntity{
			ID:            "minecraft:brushable_block",
			X:             sp[0],
			Y:             sp[1],
			Z:             sp[2],
			LootTable:     "minecraft:archaeology/desert_well",
			LootTableSeed: blockPosAsLong(sp[0], sp[1], sp[2]),
		})
	}
	return true
}
